// The everythings mod: Everythings in a pane beside the transcript.
//
// This file is the engine boundary. The engine follows `$` only into
// functions declared in the file whose hook received it, so every hook lives
// here, and `ports($)` below is the one place the mod spells out `$.mcp`,
// `$.store`, `$.ui`, `$.prompt`, `$.clock` and `$.state`. The logic is in the
// other files, written against Ports: nav.ts (screens and reads), cache.ts
// (what the session's calls carried), server.ts (which MCP server),
// blocked.ts (when Claude Code refuses the pane's calls), ask.ts (asking
// Claude to open a page or run a search), writes.ts (the person's own mark
// and comment, the pane's only writes), follow.ts (push follow),
// showThing.ts (the tool), pane.tsx (the drawing), data.ts (payloads). A
// new feature is a file of that kind plus its hook here; the state it reads
// is declared in ../types/index.d.ts.

import { atom, read, update } from 'claude-code';
import type { EngineInterface, Register, Timer } from 'claude-code';

import { askClaude } from './ask';
import { EMPTY_CACHE } from './cache';
import { IDLE_LOAD, IDLE_WRITES, INITIAL_VIEW, PANE_ID, PANE_TITLE } from './data';
import { observeCall } from './follow';
import { readSnapshot, refreshView, resumeFollow, runSearch, unfilledPage } from './nav';
import { drawPane, paneActions } from './pane';
import { cellOf, type Ports } from './ports';
import { SHOW_THING, showThing } from './showThing';

const viewAtom = atom({ plugin: 'everythings', key: 'view' } as const, INITIAL_VIEW);
// Shaped: after a hot reload that changes the cache's shape, bump the tag
// and the old value reads as absent instead of drawing in the old shape.
const cacheAtom = atom({ plugin: 'everythings', key: 'cache' } as const, EMPTY_CACHE, { shape: 'v3' });
const loadAtom = atom({ plugin: 'everythings', key: 'load' } as const, IDLE_LOAD);
const followAtom = atom({ plugin: 'everythings', key: 'follow' } as const, true);
const serverAtom = atom({ plugin: 'everythings', key: 'server' } as const, null);
const blockedAtom = atom({ plugin: 'everythings', key: 'blocked' } as const, null);
const noteDismissedAtom = atom({ plugin: 'everythings', key: 'noteDismissed' } as const, false);
const askedAtom = atom({ plugin: 'everythings', key: 'asked' } as const, null);
const freshAtom = atom({ plugin: 'everythings', key: 'fresh' } as const, {});
const defaultsAskedAtom = atom({ plugin: 'everythings', key: 'defaultsAsked' } as const, []);
const writesAtom = atom({ plugin: 'everythings', key: 'writes' } as const, IDLE_WRITES, { shape: 'v2' });

/** The engine, as the logic files may use it. A write that changes nothing is skipped (cellOf). */
function ports($: EngineInterface): Ports {
  return {
    view: cellOf(
      () => read($, viewAtom),
      change => update($, viewAtom, change),
    ),
    // The cache is large and every record makes a new one, so only the same value counts as equal.
    cache: cellOf(
      () => read($, cacheAtom),
      change => update($, cacheAtom, change),
      Object.is,
    ),
    load: cellOf(
      () => read($, loadAtom),
      change => update($, loadAtom, change),
    ),
    follow: cellOf(
      () => read($, followAtom),
      change => update($, followAtom, change),
    ),
    server: cellOf(
      () => read($, serverAtom),
      change => update($, serverAtom, change),
    ),
    blocked: cellOf(
      () => read($, blockedAtom),
      change => update($, blockedAtom, change),
    ),
    noteDismissed: cellOf(
      () => read($, noteDismissedAtom),
      change => update($, noteDismissedAtom, change),
    ),
    asked: cellOf(
      () => read($, askedAtom),
      change => update($, askedAtom, change),
    ),
    fresh: cellOf(
      () => read($, freshAtom),
      change => update($, freshAtom, change),
    ),
    defaultsAsked: cellOf(
      () => read($, defaultsAskedAtom),
      change => update($, defaultsAskedAtom, change),
    ),
    writes: cellOf(
      () => read($, writesAtom),
      change => update($, writesAtom, change),
    ),
    now: () => $.clock.now(),
    mcpCall: (server, tool, args) => $.mcp.call(server, tool, args),
    mcpConnect: async server => {
      const answer = await $.mcp.connect(server);
      return answer.isConnected
        ? { isConnected: true, server: answer.server }
        : { isConnected: false, message: answer.message };
    },
    storeGet: key => $.store.get(key),
    storeSet: (key, value) => $.store.set(key, value),
    openPane: async () => void (await $.ui.open({ id: PANE_ID, title: PANE_TITLE })),
    isPaneOpen: async () => (await $.ui.panes()).some(pane => pane.id === PANE_ID),
    askClaude: async text => (await $.prompt.submit({ text, asUser: true })).drop === undefined,
    copy: async (text, surface) => (await $.ui.copy({ text, surface })).isCopied,
  };
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'things',
      description: 'Open the Everythings pane: your workspaces and things, following what the agent writes',
    });
    await $.command.register({
      name: 'findthing',
      description: 'Search your Everythings things in every workspace and list them in the pane',
      argumentHint: '<query>',
    });
    await $.tool.register(SHOW_THING);
    return next(e);
  });

  // `/things` opens the pane on the view it last showed, arms follow,
  // and reads that view again. A screen that read leaves empty asks Claude
  // for the page, so the pane never opens on a blank or an error alone:
  // Claude's own calls reach the connector under whatever name it runs, and
  // teach the pane its server. The engine refuses a prompt submitted from
  // this hook (it would wait on the turn the hook holds), so the ask goes
  // out from a one-shot `$.clock.after` once the command has returned, and
  // only if the screen is still empty then.
  on('command.run', { command: 'things' }, async $ => {
    const p = ports($);
    await p.openPane();
    await resumeFollow(p);
    await refreshView(p);
    if ((await unfilledPage(p)) !== null) $.clock.after(ASK_MS, () => void askIfUnfilled($));
    return {};
  });

  // `/findthing <query>` opens the pane on the search's hits, from one
  // search_things call of the pane's own, and pauses follow. A search the
  // pane could not run (refused, failed, or its reads blocked) is asked of
  // Claude once, the way `/things` asks for an empty page: from a one-shot
  // `$.clock.after` once the command has returned. The agent's own
  // search_things answer then fills the list through the follow hook.
  on('command.run', { command: 'findthing' }, async ($, e) => {
    const p = ports($);
    await p.openPane();
    await runSearch(p, e.args);
    if ((await unfilledPage(p)) !== null) $.clock.after(ASK_MS, () => void askIfUnfilled($));
    return {};
  });

  // The model's `mcp__everythings__show_thing`.
  on('tool.call', { tool: 'mcp__everythings__show_thing' }, async ($, e) => ({
    result: await showThing(ports($), e as unknown as Record<string, unknown>),
  }));

  // Push follow and the session cache. The matcher admits the tools in
  // UNIQUE_TOOLS and the followed, recorded or writing ones of GENERIC_TOOLS
  // (data.ts), on any server, so no other call (Bash, Read, another server's
  // tools) reaches the plugin. The call goes on as it came and its result
  // comes back as it was; nothing that follow does may change or break it.
  on(
    'tool.call',
    {
      tool: /^mcp__.+__(?:what_changed|my_reception|search_things|get_thing|get_thing_view|get_workspace_view|list_things|list_child_things|recent_things|create_thing|update_thing|delete_thing|restore_thing|move_thing|reorder_things|copy_thing|claim_thing|release_thing|request_input|answer_request|resolve_request|list_requests|add_comment|add_mark|remove_mark|resolve_mention|list_workspaces|get_workspace|list_comments|list_marks|create_workspace|rename_workspace)$/,
    },
    async ($, e, next) => {
      const ran = await next(e);
      try {
        await observeCall(ports($), e.tool, e as unknown as Record<string, unknown>, ran);
      } catch {
        // Follow is a convenience; the call's own result is what matters.
      }
      return ran;
    },
  );

  on('ui.render', { component: 'Pane', requestId: 'everythings' }, async ($, e) => {
    const p = ports($);
    return drawPane($.ui.resolve(e), e.surface, await readSnapshot(p), paneActions(p));
  });

  // After a press, a submitted comment or a picked workspace in the pane,
  // the pane asks for the keyboard back, once. The element acted on leaves
  // the redrawn tree (a posted comment's field comes back under a new key)
  // and the pane loses the keyboard with it (seen live 2026-10-03 in the
  // desktop app), so the next click only took focus and pressed nothing.
  // A one-shot `$.clock.after`, started by the
  // person's act and replaced by the next one; it runs once. Nothing asks
  // again later: a second ask that fell between a click's focus and its
  // press was seen to swallow the press. The phone has no keyboard to give,
  // and a closed pane is left closed.
  on('ui.press', { plugin: 'everythings', component: 'Pane', requestId: 'everythings' }, async ($, e, next) => {
    const pressed = await next(e);
    if (e.surface !== 'mobile') refocusSoon($);
    return pressed;
  });
  on('ui.input', { plugin: 'everythings', component: 'Pane', requestId: 'everythings' }, async ($, e, next) => {
    const typed = await next(e);
    if (e.kind === 'submit' && e.surface !== 'mobile') refocusSoon($);
    return typed;
  });
  on('ui.select', { plugin: 'everythings', component: 'Pane', requestId: 'everythings' }, async ($, e, next) => {
    const picked = await next(e);
    if (e.surface !== 'mobile') refocusSoon($);
    return picked;
  });
};

/** How long after `/things` or `/findthing` returns an empty pane asks Claude for its page. */
const ASK_MS = 100;

/** Asks Claude for the page on screen when nothing draws there; once per page (ask.ts). */
async function askIfUnfilled($: EngineInterface): Promise<void> {
  try {
    const p = ports($);
    const target = await unfilledPage(p);
    if (target !== null) await askClaude(p, target);
  } catch {
    // The pane keeps its notice and the ask Button.
  }
}

/** How long after a press the pane asks for the keyboard back. */
const REFOCUS_MS = 200;
/** The refocus an act started and that has not run yet; a later act replaces it. */
let pendingRefocus: Timer | null = null;

/** Asks for the keyboard back REFOCUS_MS from now, in place of an ask still pending. */
function refocusSoon($: EngineInterface): void {
  pendingRefocus?.cancel();
  pendingRefocus = $.clock.after(REFOCUS_MS, () => {
    pendingRefocus = null;
    void refocusPane($);
  });
}

/** Asks for the keyboard for the open pane, unless it holds it. A refusal (text in the composer, a dialog) is silent. */
async function refocusPane($: EngineInterface): Promise<void> {
  try {
    const pane = (await $.ui.panes()).find(one => one.id === PANE_ID);
    if (!pane || pane.isFocused) return;
    await $.ui.open({ id: PANE_ID, title: PANE_TITLE, focus: true });
  } catch {
    // The pane goes on without the keyboard.
  }
}

files.hooks/ask.ts:
// Asking Claude to open a page the pane knows only by name.
//
// A tile the agent has not read has only a name and an emoji in the cache,
// and a workspace may have nothing listed yet. When the pane cannot fill the
// page itself (Claude Code refuses its reads, or a read failed), a Button
// submits one prompt as the person, naming the page by its id alone. Names
// are written by other members and by agents, and the prompt reads as the
// person's own words, so no name goes into it; an id that is not a plain
// id sends nothing. The agent then reads the page, and the follow hook
// records what that call carried, which fills it. `asked` names the page
// asked about, so the Button stays gone until the page fills or the person
// leaves the page.
//
// A search (`/findthing`) the pane could not run itself is asked for the
// same way. Its query is the person's own typed text, so it goes into the
// prompt, on one line; the agent's search_things answer then fills the list.

import type { EverythingsCache, EverythingsView } from '../types';
import { landingOf } from './cache';
import { cleanQuery, searchKey } from './data';
import type { Ports } from './ports';

/** What the pane may ask Claude to open. A workspace with no id is the one the pane opens on. */
export type AskTarget =
  | { kind: 'thing'; id: string }
  | { kind: 'workspace'; id: string | null }
  | { kind: 'search'; query: string };

/** The ids the server mints: letters, digits and dashes. */
const PLAIN_ID = /^[A-Za-z0-9-]{1,64}$/;

function keyOf(target: AskTarget): string {
  if (target.kind === 'search') return `search:${searchKey(target.query)}`;
  return target.kind === 'thing' ? `thing:${target.id}` : `workspace:${target.id ?? ''}`;
}

/** The page a view shows, as `asked` names it. */
export function askKey(view: EverythingsView, cache: EverythingsCache): string {
  if (view.kind === 'search') return keyOf({ kind: 'search', query: view.query });
  return view.kind === 'thing'
    ? keyOf({ kind: 'thing', id: view.thingId })
    : keyOf({ kind: 'workspace', id: landingOf(cache, view.workspaceId) });
}

/**
 * The prompt, in the person's words, naming the page by its id (a search by
 * the query they typed); null when the id is not a plain id or the query is empty.
 */
export function askText(target: AskTarget): string | null {
  if (target.kind === 'search') {
    const query = cleanQuery(target.query);
    return query ? `Search my Everythings things for "${query}" with search_things.` : null;
  }
  if (target.kind === 'workspace' && target.id === null) return 'Show me my default Everythings workspace in the Everythings pane.';
  if (target.id === null || !PLAIN_ID.test(target.id)) return null;
  return `Show me Everythings ${target.kind} ${target.id} in the Everythings pane.`;
}

/**
 * Submits one prompt as the person, once per pending page. The press marks
 * the page asked before it submits, so a second press finds the mark and
 * submits nothing. A prompt that did not enter clears the mark, so the
 * Button comes back.
 */
export async function askClaude(p: Ports, target: AskTarget): Promise<void> {
  const text = askText(target);
  if (text === null) return;
  const key = keyOf(target);
  let isMine = false;
  await p.asked.update(asked => {
    isMine = asked !== key;
    return key;
  });
  if (!isMine) return;
  let hasEntered = false;
  try {
    hasEntered = await p.askClaude(text);
  } catch {
    // Cleared below, as a prompt that did not enter.
  }
  if (!hasEntered) await p.asked.update(asked => (asked === key ? null : asked));
}

/** After the screen changed: an ask for a page no longer on screen goes, so its Button comes back there. */
export async function leaveAsk(p: Ports): Promise<void> {
  const asked = await p.asked.read();
  if (asked === null) return;
  const key = askKey(await p.view.read(), await p.cache.read());
  if (key !== asked) await p.asked.update(now => (now === asked ? null : now));
}

files.hooks/cache.ts:
// The session cache: what the agent's own Everythings calls carried and what
// the pane's reads brought, merged per thing and per workspace. The pane
// draws from it, so a thing the agent just wrote shows in full even when
// Claude Code refuses the pane's own read (under auto permission mode it
// may). Pure functions over EverythingsCache; nav.ts, follow.ts and writes.ts write the
// result to `$.state`.
//
// Bounds: at most THINGS_MAX things, and only the PAGES_KEPT whose pages
// were seen last keep content and sections; the rest keep a name and place.
// Each page is bounded on the way in (data.ts), so the cache stays around a
// megabyte at worst. Each thing also keeps at most 12 marks for its list row
// (ROW_MARKS_KEPT, a name up to 100 characters and an emoji up to 32): about
// 2,000 characters a thing, 600,000 over 300 things, only when every mark
// name is near its limit.

import type {
  EverythingsCache,
  EverythingsCachedThing,
  EverythingsChildren,
  EverythingsComments,
  EverythingsDefaultMark,
  EverythingsMark,
  EverythingsThingRef,
  EverythingsView,
} from '../types';
import {
  asRef,
  commentText,
  fitGrid,
  fitPage,
  isRecord,
  looksLikeHtml,
  num,
  parseComments,
  parseContent,
  parseChildren,
  parseDefaultMarks,
  parseGridView,
  parseMarks,
  parseRefs,
  parseRequest,
  parseThing,
  parseThingView,
  parseWorkspaces,
  searchKey,
  str,
  toRowMarks,
  type DrawnGrid,
  type DrawnHit,
  type DrawnPage,
  type DrawnSearch,
  type GridRecord,
  type ThingRecord,
  type ThingViewRecord,
} from './data';

export const THINGS_MAX = 300;
export const PAGES_KEPT = 8;
const ORDER_IDS_MAX = 300;
const ORDERS_MAX = 50;
const DELETED_MAX = 200;
const WORKSPACES_MAX = 200;
const SEARCHES_MAX = 10;

/** Who a comment the agent added in this session shows as, until a read brings the server's row. */
export const SESSION_AUTHOR = 'This session';
/** Who a comment the person added from the pane shows as, until a read brings the server's row. */
export const PERSON_AUTHOR = 'You';

export const EMPTY_CACHE: EverythingsCache = {
  tick: 0,
  things: {},
  workspaces: [],
  defaultWorkspaceId: null,
  order: {},
  deleted: {},
  defaultMarks: {},
  searches: {},
};

const PAGE_FIELDS: readonly string[] = ['content', 'isContentCut', 'request', 'marks', 'children', 'comments'];
const NO_CHILDREN: EverythingsChildren = { things: [], count: 0, truncated: false };
const NO_COMMENTS: EverythingsComments = { list: [], count: 0, truncated: false };

/** A cache being written: one record's worth of changes, stamped with one tick. */
type Draft = {
  tick: number;
  /** A thing recorded after this tick knows better than the record being applied. */
  since: number;
  things: Record<string, EverythingsCachedThing>;
  workspaces: EverythingsCache['workspaces'];
  defaultWorkspaceId: string | null;
  order: EverythingsCache['order'];
  deleted: Record<string, number>;
  defaultMarks: EverythingsCache['defaultMarks'];
  searches: EverythingsCache['searches'];
};

/** `since`: the tick a read started at; an observed call is as new as the cache. */
function open(cache: EverythingsCache, since = cache.tick): Draft {
  return {
    tick: cache.tick + 1,
    since,
    things: { ...cache.things },
    workspaces: [...cache.workspaces],
    defaultWorkspaceId: cache.defaultWorkspaceId,
    order: { ...cache.order },
    deleted: { ...cache.deleted },
    defaultMarks: { ...cache.defaultMarks },
    searches: { ...cache.searches },
  };
}

/** Merges what a record carried into the cached thing. Fields it did not carry stay as they were. */
function put(d: Draft, record: ThingRecord): void {
  const gone = d.deleted[record.id];
  if (gone !== undefined) {
    // Deleted after the read began: its answer predates the delete.
    if (gone > d.since) return;
    delete d.deleted[record.id];
  }
  const old = d.things[record.id];
  if (!old && record.name === undefined) return;
  // Something newer was recorded since the read began: fill gaps only.
  const isStale = old !== undefined && old.seen > d.since;
  const next: EverythingsCachedThing = old
    ? { ...old }
    : { id: record.id, name: record.name ?? 'Untitled', emoji: record.emoji ?? null, seen: 0, pageSeen: 0 };
  const fields = next as unknown as Record<string, unknown>;
  let isPage = false;
  for (const [key, value] of Object.entries(record)) {
    if (key === 'id' || value === undefined) continue;
    if (isStale && fields[key] !== undefined) continue;
    fields[key] = value;
    if (PAGE_FIELDS.includes(key)) isPage = true;
    // A page's marks are the freshest the row knows, unless a newer record gave the row its own.
    if (key === 'marks' && (!isStale || next.rowMarks === undefined)) {
      next.rowMarks = toRowMarks(value as EverythingsMark[]);
    }
  }
  next.seen = d.tick;
  if (isPage) {
    next.pageSeen = d.tick;
    delete next.isPruned;
  }
  d.things[record.id] = next;
}

/** Changes a known thing's page; an unknown thing is left alone. New marks give its row the same. */
function patch(d: Draft, id: string, change: (thing: EverythingsCachedThing) => EverythingsCachedThing | null): void {
  const old = d.things[id];
  if (!old) return;
  const next = change({ ...old });
  if (!next) return;
  const rowMarks = next.marks && next.marks !== old.marks ? toRowMarks(next.marks) : next.rowMarks;
  d.things[id] = { ...next, ...(rowMarks ? { rowMarks } : {}), seen: d.tick, pageSeen: d.tick };
}

/**
 * A mark write on a thing whose page marks are unknown but whose row marks
 * are known: "created" adds one, "deleted" takes one away. Only the row
 * changes; the thing stays as much a page as it was.
 */
function patchRow(d: Draft, id: string, name: string, emoji: string | null, step: 1 | -1): void {
  const old = d.things[id];
  if (!old?.rowMarks || old.marks) return;
  const known = old.rowMarks.find(mark => mark.name === name);
  const rowMarks = known
    ? old.rowMarks.map(mark => (mark.name === name ? { ...mark, count: mark.count + step } : mark))
    : step === 1 && emoji
      ? [...old.rowMarks, { name, emoji, count: 1 }]
      : old.rowMarks;
  d.things[id] = { ...old, rowMarks: toRowMarks(rowMarks), seen: d.tick };
}

function setOrder(d: Draft, workspaceId: string, ids: string[], count: number): void {
  delete d.order[workspaceId];
  d.order[workspaceId] = { ids, count };
}

/** Adds a thing under its parent's sub-things, or to its workspace's listing at the top level. */
function attach(d: Draft, thing: EverythingsCachedThing): void {
  if (thing.parentId === null && thing.workspaceId) {
    const listed = d.order[thing.workspaceId];
    if (listed && !listed.ids.includes(thing.id)) setOrder(d, thing.workspaceId, [...listed.ids, thing.id], listed.count + 1);
  } else if (thing.parentId) {
    patch(d, thing.parentId, parent =>
      parent.children && !parent.children.things.some(child => child.id === thing.id)
        ? {
            ...parent,
            children: {
              ...parent.children,
              things: [...parent.children.things, { id: thing.id, name: thing.name, emoji: thing.emoji }],
              count: parent.children.count + 1,
            },
          }
        : null,
    );
  }
}

/** Takes a thing out of every sub-things list and listing that holds it. */
function detach(d: Draft, id: string): void {
  for (const holder of Object.values(d.things)) {
    if (holder.children?.things.some(child => child.id === id)) {
      patch(d, holder.id, parent =>
        parent.children
          ? {
              ...parent,
              children: {
                ...parent.children,
                things: parent.children.things.filter(child => child.id !== id),
                count: Math.max(0, parent.children.count - 1),
              },
            }
          : null,
      );
    }
  }
  for (const [workspaceId, listed] of Object.entries(d.order)) {
    if (listed.ids.includes(id)) {
      d.order[workspaceId] = { ids: listed.ids.filter(one => one !== id), count: Math.max(0, listed.count - 1) };
    }
  }
}

/** A delete: the thing and what is cached under it go, and stay gone for reads that began before. */
function remove(d: Draft, id: string, visited = new Set<string>()): void {
  if (visited.has(id)) return;
  visited.add(id);
  for (const child of Object.values(d.things)) {
    if (child.parentId === id) remove(d, child.id, visited);
  }
  detach(d, id);
  delete d.things[id];
  d.deleted[id] = d.tick;
}

function nameWorkspace(d: Draft, id: string | null, name: string | null): void {
  if (!id || !name) return;
  const known = d.workspaces.findIndex(ws => ws.id === id);
  if (known >= 0) d.workspaces[known] = { ...d.workspaces[known]!, name };
  else d.workspaces.push({ id, name, isDefault: false });
}

/** A listing of a workspace's top-level things, in the server's order. */
function applyListing(d: Draft, workspaceId: string, records: ThingRecord[], count: number): void {
  for (const record of records) put(d, { ...record, parentId: null, workspaceId });
  const ids = records.map(record => record.id).filter(id => d.things[id] !== undefined);
  setOrder(d, workspaceId, ids, Math.max(count, ids.length));
  if (records.length < count) return;
  // A whole listing: what it left out is no longer at the top level, unless recorded since.
  for (const thing of Object.values(d.things)) {
    if (thing.workspaceId === workspaceId && thing.parentId === null && !ids.includes(thing.id) && thing.seen <= d.since) {
      const { parentId: _gone, ...rest } = thing;
      d.things[thing.id] = rest;
    }
  }
}

function applyThingView(d: Draft, view: ThingViewRecord): void {
  const workspaceId = view.workspace?.id ?? view.thing.workspaceId;
  put(d, view.thing);
  nameWorkspace(d, view.workspace?.id ?? null, view.workspace?.name ?? null);
  let parentId: string | null = null;
  for (const ancestor of view.ancestors) {
    put(d, { ...ancestor, parentId, ...(workspaceId ? { workspaceId } : {}) });
    parentId = ancestor.id;
  }
  for (const child of view.children.records) {
    const childWorkspace = child.workspaceId ?? workspaceId;
    put(d, { ...child, parentId: view.thing.id, ...(childWorkspace ? { workspaceId: childWorkspace } : {}) });
  }
}

function applyGrid(d: Draft, grid: GridRecord): void {
  d.workspaces = grid.workspaces;
  d.defaultWorkspaceId = grid.defaultWorkspaceId;
  if (grid.landing) applyListing(d, grid.landing.workspaceId, grid.landing.things, grid.landing.count);
}

/** Keeps the cache inside its bounds; the thing on screen (`pinned`) is never pruned. */
function close(d: Draft, pinned: string | null): EverythingsCache {
  const paged = Object.values(d.things)
    .filter(thing => thing.pageSeen > 0 && thing.id !== pinned)
    .sort((a, b) => b.pageSeen - a.pageSeen);
  const room = PAGES_KEPT - (pinned !== null && (d.things[pinned]?.pageSeen ?? 0) > 0 ? 1 : 0);
  for (const thing of paged.slice(Math.max(0, room))) {
    const { content: _c, isContentCut: _x, request: _r, marks: _m, children: _h, comments: _k, ...rest } = thing;
    d.things[thing.id] = { ...rest, pageSeen: 0, isPruned: true };
  }

  let excess = Object.keys(d.things).length - THINGS_MAX;
  if (excess > 0) {
    const oldest = Object.values(d.things)
      .filter(thing => thing.id !== pinned)
      .sort((a, b) => a.seen - b.seen);
    for (const thing of oldest) {
      if (excess <= 0) break;
      delete d.things[thing.id];
      excess -= 1;
    }
  }

  const orderKeys = Object.keys(d.order);
  for (const key of orderKeys.slice(0, Math.max(0, orderKeys.length - ORDERS_MAX))) delete d.order[key];
  for (const [key, listed] of Object.entries(d.order)) {
    if (listed.ids.length > ORDER_IDS_MAX) d.order[key] = { ids: listed.ids.slice(0, ORDER_IDS_MAX), count: listed.count };
  }

  const deleted = Object.entries(d.deleted)
    .sort((a, b) => b[1] - a[1])
    .slice(0, DELETED_MAX);

  return {
    tick: d.tick,
    things: d.things,
    workspaces: d.workspaces.slice(0, WORKSPACES_MAX),
    defaultWorkspaceId: d.defaultWorkspaceId,
    order: d.order,
    deleted: Object.fromEntries(deleted),
    defaultMarks: Object.fromEntries(Object.entries(d.defaultMarks).slice(-WORKSPACES_MAX)),
    searches: Object.fromEntries(Object.entries(d.searches).slice(-SEARCHES_MAX)),
  };
}

function id(value: unknown): string | null {
  return str(value, 100);
}

/** Workspace names the search and recent listings carry beside each thing. */
function nameWorkspacesOf(d: Draft, items: unknown): void {
  for (const item of Array.isArray(items) ? items : []) {
    if (isRecord(item)) nameWorkspace(d, id(item.workspaceId), str(item.workspaceName));
  }
}

/**
 * A search_things answer: its hits go in as names and places, and, for a
 * query, the list of them in the server's order, as the latest search.
 */
function applySearch(d: Draft, query: string, r: Record<string, unknown>): void {
  const records = parseRefs(r.results);
  for (const record of records) put(d, record);
  nameWorkspacesOf(d, r.results);
  const key = searchKey(query);
  if (!key) return;
  const ids = records.map(record => record.id).filter(one => d.things[one] !== undefined);
  delete d.searches[key];
  d.searches[key] = { query, ids, count: Math.max(num(r.count, ids.length), ids.length) };
}

/** A new thing's page, from what create_thing or request_input was given. */
function created(thingId: string, args: Record<string, unknown>, extra: Partial<ThingRecord>): ThingRecord {
  const text = typeof args.content === 'string' ? args.content : '';
  return {
    id: thingId,
    name: str(args.name) ?? 'Untitled',
    emoji: str(args.emoji, 32),
    parentId: id(args.parentId),
    ...(id(args.workspaceId) ? { workspaceId: id(args.workspaceId) as string } : {}),
    // HTML is converted on the server, so its Markdown is unknown here.
    ...(looksLikeHtml(text) ? {} : parseContent(text)),
    marks: [],
    children: NO_CHILDREN,
    ...extra,
  };
}

/**
 * Records one answered Everythings call: the agent's, or the person's own
 * mark or comment from the pane. `data` is its JSON answer, null when
 * unreadable. `author` is who a comment it added shows as: the agent's
 * shows as SESSION_AUTHOR until a read brings the server's row, the
 * person's own as PERSON_AUTHOR.
 */
export function recordCall(
  cache: EverythingsCache,
  name: string,
  args: Record<string, unknown>,
  data: Record<string, unknown> | null,
  pinned: string | null,
  author = SESSION_AUTHOR,
): EverythingsCache {
  const d = open(cache);
  const r = data ?? {};
  const thingId = id(args.thingId);

  switch (name) {
    case 'get_thing_view': {
      const view = parseThingView(r);
      if (view) applyThingView(d, view);
      break;
    }
    case 'get_workspace_view': {
      const grid = parseGridView(r);
      if (grid) applyGrid(d, grid);
      break;
    }
    case 'get_thing': {
      const thing = parseThing(r);
      if (thing) put(d, thing);
      break;
    }
    case 'list_workspaces': {
      if (Array.isArray(r.workspaces)) d.workspaces = parseWorkspaces(r.workspaces);
      if ('defaultWorkspaceId' in r) d.defaultWorkspaceId = id(r.defaultWorkspaceId);
      break;
    }
    case 'get_workspace': {
      const workspaceId = id(r.id);
      nameWorkspace(d, workspaceId, str(r.name));
      const marks = parseDefaultMarks(r);
      if (workspaceId && marks) d.defaultMarks[workspaceId] = marks;
      break;
    }
    case 'list_things': {
      const workspaceId = id(args.workspaceId);
      const records = parseRefs(r.things);
      if (workspaceId) applyListing(d, workspaceId, records, num(r.count, records.length));
      break;
    }
    case 'list_child_things': {
      const parentId = id(args.parentId);
      if (!parentId) break;
      const { records, section } = parseChildren(r);
      for (const record of records) put(d, { ...record, parentId });
      put(d, { id: parentId, children: section });
      break;
    }
    case 'search_things':
      applySearch(d, typeof args.query === 'string' ? args.query : '', r);
      break;
    case 'recent_things':
      for (const record of parseRefs(r.things)) put(d, record);
      nameWorkspacesOf(d, r.things);
      break;
    case 'list_comments':
      if (thingId) put(d, { id: thingId, comments: parseComments(r) });
      break;
    case 'list_marks':
      if (thingId) put(d, { id: thingId, marks: parseMarks(r) });
      break;
    case 'create_thing': {
      const newId = id(r.thingId);
      if (!newId) break;
      put(d, created(newId, { ...args, workspaceId: r.workspaceId ?? args.workspaceId }, { request: null, comments: NO_COMMENTS }));
      const thing = d.things[newId];
      if (thing) attach(d, thing);
      break;
    }
    case 'update_thing': {
      const updatedId = id(r.thingId) ?? thingId;
      if (!updatedId) break;
      put(d, {
        id: updatedId,
        ...('name' in r && str(r.name) ? { name: str(r.name) as string } : {}),
        ...('emoji' in r ? { emoji: str(r.emoji, 32) } : {}),
        ...('content' in r ? parseContent(r.content) : {}),
      });
      break;
    }
    case 'delete_thing':
      if (thingId) remove(d, thingId);
      break;
    case 'restore_thing':
      if (thingId) delete d.deleted[thingId];
      break;
    case 'move_thing': {
      if (!thingId) break;
      const parentId = 'newParentId' in r ? id(r.newParentId) : id(args.newParentId);
      detach(d, thingId);
      put(d, { id: thingId, parentId });
      const thing = d.things[thingId];
      if (thing) attach(d, thing);
      break;
    }
    case 'copy_thing': {
      const copyId = id(r.thingId);
      if (!copyId) break;
      const source = thingId ? d.things[thingId] : undefined;
      const copy: ThingRecord = {
        id: copyId,
        name: str(r.name) ?? source?.name ?? 'Untitled',
        emoji: source?.emoji ?? null,
        parentId: id(args.targetParentId),
        ...(id(args.targetWorkspaceId) ? { workspaceId: id(args.targetWorkspaceId) as string } : {}),
        // A copy carries content, but no marks or comments.
        ...(source?.content !== undefined ? { content: source.content, isContentCut: source.isContentCut === true } : {}),
        marks: [],
        comments: NO_COMMENTS,
        ...(num(r.copiedCount, 0) === 1 ? { children: NO_CHILDREN } : {}),
      };
      put(d, copy);
      const thing = d.things[copyId];
      if (thing) attach(d, thing);
      break;
    }
    case 'add_mark': {
      // The call rides the person's token, so the mark is theirs after it,
      // "created" or "unchanged" alike. The count goes up only for a mark
      // the cache did not have as theirs: a read that came back while the
      // call ran may have counted it already.
      const markName = str(args.name, 100) ?? str(args.emoji, 32);
      const emoji = str(args.emoji, 32);
      const isCreated = r.action === 'created';
      if (!thingId || !markName || !emoji || (!isCreated && r.action !== 'unchanged')) break;
      if (isCreated) patchRow(d, thingId, markName, emoji, 1);
      patch(d, thingId, thing => {
        if (!thing.marks) return null;
        const known = thing.marks.find(mark => mark.name === markName);
        if (!known) return { ...thing, marks: [...thing.marks, { name: markName, emoji, count: 1, mine: true }] };
        if (known.mine) return null;
        return {
          ...thing,
          marks: thing.marks.map(mark =>
            mark.name === markName ? { ...mark, count: isCreated ? mark.count + 1 : mark.count, mine: true } : mark,
          ),
        };
      });
      break;
    }
    case 'remove_mark': {
      // The mark is not theirs after it, "deleted" or "unchanged" alike. The
      // count goes down only for a mark the cache still had as theirs.
      const markName = str(args.name, 100) ?? str(args.emoji, 32);
      const isDeleted = r.action === 'deleted';
      if (!thingId || !markName || (!isDeleted && r.action !== 'unchanged')) break;
      if (isDeleted) patchRow(d, thingId, markName, null, -1);
      patch(d, thingId, thing => {
        const known = thing.marks?.find(mark => mark.name === markName);
        if (!thing.marks || !known || !known.mine) return null;
        return {
          ...thing,
          marks: thing.marks
            .map(mark =>
              mark.name === markName ? { ...mark, count: isDeleted ? mark.count - 1 : mark.count, mine: false } : mark,
            )
            .filter(mark => mark.count > 0),
        };
      });
      break;
    }
    case 'add_comment': {
      const commentId = id(r.commentId);
      if (!thingId || !commentId) break;
      const text = commentText(args.content);
      patch(d, thingId, thing =>
        thing.comments
          ? {
              ...thing,
              comments: {
                ...thing.comments,
                list: [...thing.comments.list, { id: commentId, authorName: author, byAgent: null, parentId: null, text }],
                count: thing.comments.count + 1,
              },
            }
          : null,
      );
      break;
    }
    case 'request_input': {
      const askedId = id(r.thingId) ?? thingId;
      if (!askedId) break;
      // Without a thingId the call made a new thing to carry the question.
      if (!thingId) {
        put(d, created(askedId, args, {}));
        const thing = d.things[askedId];
        if (thing) attach(d, thing);
      }
      if (isRecord(r.request)) put(d, { id: askedId, request: parseRequest(r.request) });
      break;
    }
    case 'answer_request':
    case 'resolve_request':
      if (thingId && isRecord(r.request)) put(d, { id: thingId, request: parseRequest(r.request) });
      break;
    case 'resolve_mention': {
      const onThing = id(r.thingId);
      const commentId = id(r.commentId);
      const replyId = id(r.replyId);
      if (!onThing || !commentId || r.action !== 'resolved') break;
      patch(d, onThing, thing => {
        if (!thing.comments) return null;
        const list = thing.comments.list.map(comment =>
          comment.id === commentId ? { ...comment, text: comment.text.replace('@Agent', '🤖agent') } : comment,
        );
        const reply = replyId
          ? [{ id: replyId, authorName: SESSION_AUTHOR, byAgent: null, parentId: commentId, text: commentText(args.reply) }]
          : [];
        return { ...thing, comments: { ...thing.comments, list: [...list, ...reply], count: thing.comments.count + reply.length } };
      });
      break;
    }
    default:
      return cache;
  }
  return close(d, pinned);
}

/** The pane's own get_thing_view answer, read from tick `since` on. */
export function recordPage(cache: EverythingsCache, view: ThingViewRecord, since: number, pinned: string | null): EverythingsCache {
  const d = open(cache, since);
  applyThingView(d, view);
  return close(d, pinned);
}

/** A workspace's default marks, from the pane's own get_workspace answer. */
export function recordDefaultMarks(
  cache: EverythingsCache,
  workspaceId: string,
  marks: EverythingsDefaultMark[],
): EverythingsCache {
  const known = cache.defaultMarks[workspaceId];
  if (known && JSON.stringify(known) === JSON.stringify(marks)) return cache;
  return { ...cache, defaultMarks: { ...cache.defaultMarks, [workspaceId]: marks } };
}

/** The pane's own get_workspace_view answer, read from tick `since` on. */
export function recordGrid(cache: EverythingsCache, grid: GridRecord, since: number, pinned: string | null): EverythingsCache {
  const d = open(cache, since);
  applyGrid(d, grid);
  return close(d, pinned);
}

/** The pane's own search_things answer for `query`, read from tick `since` on. */
export function recordSearch(
  cache: EverythingsCache,
  query: string,
  data: Record<string, unknown>,
  since: number,
  pinned: string | null,
): EverythingsCache {
  const d = open(cache, since);
  applySearch(d, query, data);
  return close(d, pinned);
}

/**
 * The hits recorded for one query, recorded for another too: the agent ran
 * the search the pane asked for in its own words.
 */
export function aliasSearch(cache: EverythingsCache, from: string, to: string): EverythingsCache {
  const found = cache.searches[searchKey(from)];
  const key = searchKey(to);
  if (!found || !key || searchKey(from) === key) return cache;
  const { [key]: _old, ...rest } = cache.searches;
  return { ...cache, searches: { ...rest, [key]: found } };
}

/** A search's hits as known now; null while no answer for the query was recorded. */
export function searchOf(cache: EverythingsCache, query: string): DrawnSearch | null {
  const found = cache.searches[searchKey(query)];
  if (!found) return null;
  const hits: DrawnHit[] = found.ids.flatMap(one => {
    const thing = cache.things[one];
    if (!thing) return [];
    const workspace = thing.workspaceId ? cache.workspaces.find(ws => ws.id === thing.workspaceId) : undefined;
    return [
      {
        ...asRef(thing),
        workspaceId: thing.workspaceId ?? null,
        workspaceName: workspace?.name ?? null,
        marks: thing.rowMarks ?? null,
      },
    ];
  });
  return { query: found.query, hits, count: found.count, truncated: hits.length < found.count };
}

/** One thing's page as known now; null when the session has seen nothing of it. */
export function pageOf(cache: EverythingsCache, thingId: string): DrawnPage | null {
  const thing = cache.things[thingId];
  if (!thing) return null;
  const workspace = thing.workspaceId ? cache.workspaces.find(ws => ws.id === thing.workspaceId) : undefined;
  const parent = thing.parentId ? cache.things[thing.parentId] : undefined;
  const defaults = thing.workspaceId ? (cache.defaultMarks[thing.workspaceId] ?? null) : null;
  return fitPage(thing, workspace?.name ?? null, parent ? asRef(parent) : null, defaults, id => cache.things[id]?.rowMarks);
}

/**
 * True when the cache holds a thing's whole page, as a get_thing_view
 * answer leaves it: content and every section.
 */
export function isWholePage(cache: EverythingsCache, thingId: string): boolean {
  const thing = cache.things[thingId];
  return (
    thing !== undefined &&
    thing.content !== undefined &&
    thing.marks !== undefined &&
    thing.children !== undefined &&
    thing.comments !== undefined
  );
}

/** What a view draws from the cache, as one string: two caches that give the same draw the same. */
export function drawnOf(cache: EverythingsCache, view: EverythingsView): string {
  if (view.kind === 'search') return JSON.stringify(searchOf(cache, view.query));
  return JSON.stringify(view.kind === 'thing' ? pageOf(cache, view.thingId) : gridOf(cache, view.workspaceId));
}

/** The workspace a grid with none named lands on: the default, else the first known. */
export function landingOf(cache: EverythingsCache, workspaceId: string | null): string | null {
  if (workspaceId) return workspaceId;
  if (cache.defaultWorkspaceId) return cache.defaultWorkspaceId;
  if (cache.workspaces[0]) return cache.workspaces[0].id;
  const newest = Object.values(cache.things)
    .filter(thing => thing.workspaceId)
    .sort((a, b) => b.seen - a.seen)[0];
  return newest?.workspaceId ?? null;
}

/** A workspace's grid as known now: the listing's order first, then top-level things seen since. */
export function gridOf(cache: EverythingsCache, workspaceId: string | null): DrawnGrid {
  const landing = landingOf(cache, workspaceId);
  if (!landing) return fitGrid(cache.workspaces, null);
  const listed = cache.order[landing];
  const isTop = (thing: EverythingsCachedThing | undefined): thing is EverythingsCachedThing =>
    thing !== undefined && thing.workspaceId === landing && thing.parentId === null;
  const inOrder = (listed?.ids ?? []).map(one => cache.things[one]).filter(isTop);
  const placed = new Set(inOrder.map(thing => thing.id));
  const others = Object.values(cache.things)
    .filter(thing => isTop(thing) && !placed.has(thing.id))
    .sort((a, b) => a.seen - b.seen);
  const things: EverythingsThingRef[] = [...inOrder, ...others].map(asRef);
  return fitGrid(cache.workspaces, {
    workspaceId: landing,
    things,
    count: Math.max(listed?.count ?? 0, things.length),
    isListed: listed !== undefined,
  });
}

files.hooks/data.ts:
// Pure helpers: tool names, payload parsing, and the text bounds the
// surfaces enforce. Nothing here touches `$`.
//
// Payload shapes follow apps/web/src/app/api/mcp/route.ts. A parser keeps
// only what the payload carried: a field it did not carry stays undefined,
// so the cache (cache.ts) knows it is unknown rather than empty.

import type { McpToolResult, ToolCallResult } from 'claude-code';

import type {
  EverythingsCachedThing,
  EverythingsChildren,
  EverythingsComment,
  EverythingsComments,
  EverythingsDefaultMark,
  EverythingsLoad,
  EverythingsRowMark,
  EverythingsMark,
  EverythingsRequest,
  EverythingsThingRef,
  EverythingsView,
  EverythingsWorkspace,
  EverythingsWrites,
} from '../types';

/** The pane's id: `$.ui.open`, `$.ui.panes` and the Pane render matcher. */
export const PANE_ID = 'everythings';
export const PANE_TITLE = 'Everythings';

export const APP_ORIGIN = 'https://www.everythings.app';

/** What a thing with no emoji shows, as on the web and the phone (`thing.emoji || '📄'`). */
export const NO_EMOJI = '📄';

export const INITIAL_VIEW: EverythingsView = { kind: 'grid', workspaceId: null };
export const IDLE_LOAD: EverythingsLoad = {
  seq: 0,
  key: '',
  isLoading: false,
  error: null,
  isNotConnected: false,
};

/** Markdown and Text both refuse a string longer than this. */
export const TEXT_MAX = 10_000;
/**
 * The engine refuses a drawing holding more than 100,000 characters of text,
 * counting every Text, label, Markdown text, link target and pressable link
 * (keys are free). A page keeps its own strings under this budget, and
 * PAGE_CHROME reserves room for what the pane adds around them: the header,
 * the status lines, notes and labels.
 */
const PAGE_TEXT_BUDGET = 95_000;
const PAGE_CHROME = 2_000;
const COMMENT_MAX = 2_000;
const COMMENTS_KEPT = 100;
/** Comment text kept per thing; more could never fit a page. */
const COMMENTS_TEXT_KEPT = 60_000;
const NAME_MAX = 200;

/**
 * The reads the pane makes of its own: a grid, a thing's page, a workspace's
 * default marks, and the search `/findthing` runs.
 */
export const READ_TOOLS = {
  grid: 'get_workspace_view',
  thing: 'get_thing_view',
  defaults: 'get_workspace',
  search: 'search_things',
} as const;

/**
 * The writes the pane makes, each only on the person's own action: their
 * mark on a press, their comment on a submit. It calls no other tool.
 */
export const WRITE_TOOLS = { addMark: 'add_mark', removeMark: 'remove_mark', comment: 'add_comment' } as const;

export const IDLE_WRITES: EverythingsWrites = {
  pending: {},
  commenting: {},
  posted: {},
  error: null,
  blocked: null,
  last: null,
};

/** A mark or comment marker older than this is one an earlier load left: it blocks nothing. */
export const WRITE_STALE_MS = 30_000;

/** The most a comment holds (TEXT_LIMITS.commentContent on the server). */
export const COMMENT_LIMIT = 10_000;

/**
 * Tools of the Everythings MCP server (apps/web/src/app/api/mcp/route.ts)
 * whose names only it uses. An answered call of one names the server: the
 * pane reads from that server from then on, in this session and later ones.
 */
export const UNIQUE_TOOLS: ReadonlySet<string> = new Set([
  'what_changed', 'my_reception', 'search_things', 'get_thing', 'get_thing_view',
  'get_workspace_view', 'list_things', 'list_child_things', 'recent_things',
  'create_thing', 'update_thing', 'delete_thing', 'restore_thing', 'move_thing',
  'reorder_things', 'copy_thing', 'claim_thing', 'release_thing', 'request_input',
  'answer_request', 'resolve_request', 'list_requests',
]);

/**
 * Its tools whose names another server may use too (a Notion `search`, a
 * Linear `add_comment`). A call of one counts as an Everythings call only on
 * the server already learned.
 */
export const GENERIC_TOOLS: ReadonlySet<string> = new Set([
  'search', 'fetch', 'list_workspaces', 'get_workspace', 'create_workspace',
  'rename_workspace', 'list_comments', 'list_marks', 'list_trash', 'add_comment',
  'add_mark', 'remove_mark', 'list_mentions', 'resolve_mention',
]);

/** The Everythings tools that only read. An answered call of any other is a write. */
export const READ_ONLY_TOOLS: ReadonlySet<string> = new Set([
  'what_changed', 'my_reception', 'search_things', 'get_thing', 'get_thing_view',
  'get_workspace_view', 'list_things', 'list_child_things', 'recent_things', 'list_requests',
  'search', 'fetch', 'list_workspaces', 'get_workspace', 'list_comments', 'list_marks',
  'list_trash', 'list_mentions',
]);

/** The writes the pane follows. */
export const FOLLOWED_WRITES: ReadonlySet<string> = new Set([
  'create_thing', 'update_thing', 'move_thing', 'delete_thing', 'restore_thing',
  'add_mark', 'remove_mark', 'add_comment', 'request_input', 'answer_request',
  'resolve_request', 'copy_thing', 'resolve_mention',
]);

/**
 * Writes whose thing id is in the result: the new thing, the copy, the thing
 * a question was asked on, the thing of the comment a mention was in.
 */
const ID_FROM_RESULT: ReadonlySet<string> = new Set([
  'create_thing', 'copy_thing', 'request_input', 'resolve_mention',
]);

/** What a followed write asks of the pane. */
export type WriteTarget = { kind: 'open'; thingId: string } | { kind: 'deleted'; thingId: string };

export function viewKey(view: EverythingsView): string {
  if (view.kind === 'search') return `search:${searchKey(view.query)}`;
  return view.kind === 'grid' ? `grid:${view.workspaceId ?? ''}` : `thing:${view.thingId}`;
}

/** The most of a query the pane keeps, sends and shows. */
export const QUERY_MAX = 200;

/** A query as the person typed it, on one line and in bounds; empty when they typed none. */
export function cleanQuery(value: unknown): string {
  return clean(value, QUERY_MAX).replace(/\s+/g, ' ').trim();
}

/** What makes two queries the same search: case and spacing aside. */
export function searchKey(query: string): string {
  return cleanQuery(query).toLowerCase();
}

export function thingUrl(workspaceId: string, thingId: string): string {
  return `${APP_ORIGIN}/workspaces/${encodeURIComponent(workspaceId)}/things/${encodeURIComponent(thingId)}`;
}

/**
 * Splits `mcp__<server>__<tool>` at its last `__`. In the desktop app the
 * Everythings connector runs under a UUID; in a terminal under `everythings`
 * or `claude_ai_Everythings`. Either way the server part is a name
 * `$.mcp.call` takes.
 */
export function splitToolName(tool: string): { server: string; name: string } | null {
  if (!tool.startsWith('mcp__')) return null;
  const rest = tool.slice('mcp__'.length);
  const at = rest.lastIndexOf('__');
  if (at <= 0) return null;
  const server = rest.slice(0, at);
  const name = rest.slice(at + 2);
  return server && name ? { server, name } : null;
}

export function isAnswered(ran: ToolCallResult): boolean {
  return ran.deny === undefined && ran.isError !== true;
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function parseJson(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
}

function blocksJson(blocks: unknown[]): unknown {
  const text = blocks.map(block => (isRecord(block) && typeof block.text === 'string' ? block.text : '')).join('');
  return parseJson(text);
}

/**
 * A tool call's JSON answer, wherever the engine put it: the result record
 * itself, its structured content, its content blocks, or the text the model
 * read. Null when none of them holds a JSON object.
 */
export function answerData(ran: ToolCallResult): Record<string, unknown> | null {
  const result: unknown = ran.result;
  const candidates: unknown[] = [];
  if (isRecord(result)) {
    candidates.push(result.structuredContent);
    if (Array.isArray(result.content)) candidates.push(blocksJson(result.content));
    else candidates.push(result);
  }
  if (Array.isArray(result)) candidates.push(blocksJson(result));
  if (typeof result === 'string') candidates.push(parseJson(result));
  if (typeof ran.text === 'string') candidates.push(parseJson(ran.text));
  for (const one of candidates) if (isRecord(one)) return one;
  return null;
}

/** Which thing a followed write is about, or null when it names none. */
export function writeTarget(
  name: string,
  args: Record<string, unknown>,
  data: Record<string, unknown> | null,
): WriteTarget | null {
  const fromArgs = typeof args.thingId === 'string' && args.thingId ? args.thingId : null;
  const fromResult = data && typeof data.thingId === 'string' && data.thingId ? data.thingId : null;
  const thingId = ID_FROM_RESULT.has(name) ? (fromResult ?? fromArgs) : fromArgs;
  if (!thingId) return null;
  return name === 'delete_thing' ? { kind: 'deleted', thingId } : { kind: 'open', thingId };
}

/** An MCP result as JSON data, or the server's error text as one line. */
export function readResult(result: McpToolResult): { data: Record<string, unknown> } | { error: string } {
  const text = result.content
    .map(block => (typeof block.text === 'string' ? block.text : ''))
    .join('\n')
    .trim();
  if (result.isError) return { error: oneLine(text) || 'The Everythings server reported an error.' };
  if (isRecord(result.structuredContent)) return { data: result.structuredContent };
  const data = parseJson(text);
  return isRecord(data) ? { data } : { error: 'The Everythings server sent a reply the pane cannot read.' };
}

/** Strips control characters (tab and newline survive when `isMultiline`). */
export function clean(value: unknown, max: number, isMultiline = false): string {
  if (typeof value !== 'string') return '';
  const text = value
    .replace(/\r\n?/g, '\n')
    .replace(isMultiline ? /[\u0000-\u0008\u000b-\u001f\u007f]/g : /[\u0000-\u001f\u007f]/g, ' ');
  return cut(text, max);
}

/** Cuts at `max` UTF-16 units without splitting a surrogate pair. */
function cut(text: string, max: number): string {
  if (text.length <= max) return text;
  const code = text.charCodeAt(max - 1);
  return text.slice(0, code >= 0xd800 && code <= 0xdbff ? max - 1 : max);
}

/** Cells one character takes on a terminal: 2 for wide CJK and most emoji, else 1. */
function cellsOf(char: string): number {
  const code = char.codePointAt(0) ?? 0;
  const isWide =
    (code >= 0x1100 && code <= 0x115f) ||
    (code >= 0x2e80 && code <= 0xa4cf) ||
    (code >= 0xac00 && code <= 0xd7a3) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xfe30 && code <= 0xfe4f) ||
    (code >= 0xff00 && code <= 0xff60) ||
    (code >= 0xffe0 && code <= 0xffe6) ||
    (code >= 0x1f300 && code <= 0x1faff) ||
    (code >= 0x20000 && code <= 0x3fffd);
  return isWide ? 2 : 1;
}

/** `text` cut to fit `cells` terminal cells, ending in an ellipsis when cut. */
export function clip(text: string, cells: number): string {
  const chars = Array.from(text);
  if (chars.reduce((sum, char) => sum + cellsOf(char), 0) <= cells) return text;
  let kept = '';
  let used = 0;
  for (const char of chars) {
    used += cellsOf(char);
    if (used > cells - 1) break;
    kept += char;
  }
  return `${kept.trimEnd()}…`;
}

export function oneLine(text: string): string {
  return clean(text.split('\n').find(line => line.trim()) ?? '', 300).trim();
}

export function str(value: unknown, max = NAME_MAX): string | null {
  const text = clean(value, max).trim();
  return text ? text : null;
}

export function num(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function list(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

/** A thing as one payload carried it; a field it did not carry is undefined. */
export type ThingRecord = Omit<EverythingsCachedThing, 'name' | 'emoji' | 'seen' | 'pageSeen'> & {
  name?: string;
  emoji?: string | null;
};

/** A thing in a listing: its id, name and emoji, and where it sits when the listing says. */
export function parseRef(item: unknown): ThingRecord | null {
  if (!isRecord(item)) return null;
  const id = str(item.id, 100);
  if (!id) return null;
  const record: ThingRecord = { id, name: str(item.name) ?? 'Untitled', emoji: str(item.emoji, 32) };
  const workspaceId = str(item.workspaceId, 100);
  if (workspaceId) record.workspaceId = workspaceId;
  if ('parentId' in item) record.parentId = str(item.parentId, 100);
  const marks = parseRowMarks(item.marks);
  if (marks !== null) record.rowMarks = marks;
  return record;
}

/** At most this many marks are kept per thing for its list row. */
export const ROW_MARKS_KEPT = 12;

/** Marks as a list row keeps them: each with a count, at most ROW_MARKS_KEPT. */
export function toRowMarks(marks: readonly { name: string; emoji: string; count: number }[]): EverythingsRowMark[] {
  return marks
    .filter(mark => mark.count > 0)
    .slice(0, ROW_MARKS_KEPT)
    .map(mark => ({ name: mark.name, emoji: mark.emoji, count: mark.count }));
}

/** A listed thing's `marks`, which the view tools carry; null when the answer has none (the older shape). */
export function parseRowMarks(value: unknown): EverythingsRowMark[] | null {
  if (!Array.isArray(value)) return null;
  return toRowMarks(
    value.flatMap(item => {
      if (!isRecord(item)) return [];
      const name = str(item.name, 100);
      const emoji = str(item.emoji, 32);
      return name && emoji ? [{ name, emoji, count: num(item.count, 1) }] : [];
    }),
  );
}

export function parseRefs(value: unknown): ThingRecord[] {
  return list(value).flatMap(item => parseRef(item) ?? []);
}

export function asRef(record: ThingRecord): EverythingsThingRef {
  return { id: record.id, name: record.name ?? 'Untitled', emoji: record.emoji ?? null };
}

export function parseWorkspaces(value: unknown): EverythingsWorkspace[] {
  return list(value).flatMap(item => {
    if (!isRecord(item)) return [];
    const id = str(item.id, 100);
    return id ? [{ id, name: str(item.name) ?? 'Untitled', isDefault: item.isDefault === true }] : [];
  });
}

/** Thing content as the pane keeps it: at most 10,000 characters, null when empty. */
export function parseContent(value: unknown): { content: string | null; isContentCut: boolean } {
  const raw = typeof value === 'string' ? clean(value, Number.MAX_SAFE_INTEGER, true) : '';
  const kept = clean(raw, TEXT_MAX, true);
  return { content: kept.trim() ? kept : null, isContentCut: kept.length < raw.length };
}

export function parseRequest(value: unknown): EverythingsRequest | null {
  if (!isRecord(value)) return null;
  const question = str(value.question, 2_000);
  if (!question) return null;
  const answer = isRecord(value.answer) ? value.answer : null;
  return {
    question,
    options: list(value.options).flatMap(option => {
      if (!isRecord(option)) return [];
      const label = str(option.label);
      return label
        ? [{ id: str(option.id, 100) ?? label, label, description: str(option.description, 500) }]
        : [];
    }),
    status: str(value.status, 32) ?? 'open',
    createdBy: str(value.createdBy, 100),
    answer: answer
      ? {
          optionId: str(answer.optionId, 100),
          optionLabel: str(answer.optionLabel),
          comment: str(answer.comment, 2_000),
          userName: str(answer.userName, 100),
          via: str(answer.via, 16),
        }
      : null,
  };
}

export function parseMarks(value: unknown): EverythingsMark[] {
  const marks = isRecord(value) ? value.marks : value;
  return list(marks).flatMap(item => {
    if (!isRecord(item)) return [];
    const name = str(item.name, 100);
    const emoji = str(item.emoji, 32);
    return name && emoji ? [{ name, emoji, count: num(item.count, 1), mine: item.mine === true }] : [];
  });
}

/** get_workspace's `defaultMarks`, at most 8 as the workspace keeps them; null when the answer has none. */
export function parseDefaultMarks(data: unknown): EverythingsDefaultMark[] | null {
  if (!isRecord(data) || !Array.isArray(data.defaultMarks)) return null;
  return data.defaultMarks.slice(0, 8).flatMap(item => {
    if (!isRecord(item)) return [];
    const name = str(item.name, 100);
    const emoji = str(item.emoji, 32);
    return name && emoji ? [{ name, emoji }] : [];
  });
}

/** Mention tokens drawn as `@Name` (packages/shared/src/mentions.ts). */
const MENTION_TOKEN = /@\[([^\]\n]*)\]\((user:[^)\s]+|agent)\)/g;

export function commentText(value: unknown): string {
  return clean(String(value ?? '').replace(MENTION_TOKEN, '@$1'), COMMENT_MAX, true).trim();
}

/** Comments in order, as many as the cache keeps. */
export function parseComments(value: unknown): EverythingsComments {
  const page = isRecord(value) ? value : {};
  const all = list(page.comments);
  const kept: EverythingsComment[] = [];
  let room = COMMENTS_TEXT_KEPT;
  for (const item of all) {
    if (!isRecord(item)) continue;
    if (kept.length >= COMMENTS_KEPT) break;
    const id = str(item.id, 100);
    if (!id) continue;
    const text = commentText(item.content);
    if (text.length > room) break;
    room -= text.length;
    kept.push({
      id,
      authorName: str(item.authorName, 100) ?? 'Someone',
      byAgent: str(item.byAgent, 100),
      parentId: str(item.parentId, 100),
      text,
    });
  }
  const count = num(page.count, all.length);
  return { list: kept, count, truncated: page.truncated === true || kept.length < count };
}

export function parseChildren(value: unknown): { records: ThingRecord[]; section: EverythingsChildren } {
  const page = isRecord(value) ? value : {};
  const records = parseRefs(page.things);
  const count = num(page.count, records.length);
  return {
    records,
    section: { things: records.map(asRef), count, truncated: page.truncated === true || records.length < count },
  };
}

/** get_thing's answer, or the `thing` of get_thing_view's. */
export function parseThing(value: unknown): ThingRecord | null {
  if (!isRecord(value)) return null;
  const id = str(value.id, 100);
  if (!id) return null;
  return {
    id,
    name: str(value.name) ?? 'Untitled',
    emoji: str(value.emoji, 32),
    ...parseContent(value.content),
    ...(str(value.workspaceId, 100) ? { workspaceId: str(value.workspaceId, 100) as string } : {}),
    ...('parentId' in value ? { parentId: str(value.parentId, 100) } : {}),
    agent: str(value.updatedByAgent, 100) ?? str(value.createdByAgent, 100),
    request: parseRequest(value.request),
  };
}

/** get_thing_view's answer: the whole page of one thing. */
export type ThingViewRecord = {
  thing: ThingRecord;
  workspace: { id: string; name: string } | null;
  ancestors: ThingRecord[];
  children: ReturnType<typeof parseChildren>;
};

export function parseThingView(data: unknown): ThingViewRecord | null {
  if (!isRecord(data)) return null;
  const thing = parseThing(data.thing);
  if (!thing) return null;
  const space = isRecord(data.workspace) ? data.workspace : {};
  const workspaceId = str(space.id, 100) ?? thing.workspaceId ?? null;
  const children = parseChildren(data.children);
  return {
    thing: { ...thing, marks: parseMarks(data.marks), comments: parseComments(data.comments), children: children.section },
    workspace: workspaceId ? { id: workspaceId, name: str(space.name) ?? 'Workspace' } : null,
    ancestors: parseRefs(data.ancestors),
    children,
  };
}

/** get_workspace_view's answer: the workspaces and the landing workspace's top-level things. */
export type GridRecord = {
  workspaces: EverythingsWorkspace[];
  defaultWorkspaceId: string | null;
  landing: { workspaceId: string; things: ThingRecord[]; count: number } | null;
};

export function parseGridView(data: unknown): GridRecord | null {
  if (!isRecord(data) || !Array.isArray(data.workspaces)) return null;
  const landing = isRecord(data.landing) ? data.landing : null;
  const landingId = landing ? str(landing.workspaceId, 100) : null;
  const things = landing ? parseRefs(landing.things) : [];
  const count = landing ? num(landing.count, things.length) : 0;
  return {
    workspaces: parseWorkspaces(data.workspaces),
    defaultWorkspaceId: str(data.defaultWorkspaceId, 100),
    landing: landing && landingId ? { workspaceId: landingId, things, count } : null,
  };
}

/** A search hit as its row draws it: the ref, its workspace, and its marks (null while unknown). */
export type DrawnHit = EverythingsThingRef & {
  workspaceId: string | null;
  workspaceName: string | null;
  marks: EverythingsRowMark[] | null;
};
/** A search as the pane draws it: the hits it still knows, in the server's order, and the server's total. */
export type DrawnSearch = { query: string; hits: DrawnHit[]; count: number; truncated: boolean };

/** Looks like HTML the server will convert, so the stored Markdown is not knowable from the input. */
export function looksLikeHtml(text: string): boolean {
  return /<\/?(p|div|br|ul|ol|li|h[1-6]|table|tr|td|strong|em|b|i|a|span|blockquote|pre|code)\b[^>]*>/i.test(text);
}

/** Links in content that open another thing in the pane. */
const THING_LINK = /https:\/\/(?:www\.)?everythings\.app\/workspaces\/[A-Za-z0-9-]+\/things\/([A-Za-z0-9-]+)/g;

export function thingLinks(content: string): string[] {
  const found = new Set<string>();
  for (const match of content.matchAll(THING_LINK)) {
    if (found.size >= 256) break;
    found.add(match[0]);
  }
  return [...found];
}

export function thingIdFromLink(href: string): string | null {
  const match = new RegExp(THING_LINK.source).exec(href);
  return match ? (match[1] ?? null) : null;
}

/** One thing's page as the pane draws it: what is known, fitted to the text budget. Null is an absent section. */
export type DrawnPage = {
  id: string;
  name: string;
  emoji: string | null;
  workspaceId: string | null;
  workspaceName: string | null;
  /** The thing it sits under, as the cache knows it; null at the top level or when unknown. */
  parent: EverythingsThingRef | null;
  content: string | null;
  isContentCut: boolean;
  links: string[];
  agent: string | null;
  request: EverythingsRequest | null;
  /** Null while no read carried its marks. */
  marks: EverythingsMark[] | null;
  /** Its workspace's default marks; null while unknown. */
  defaultMarks: EverythingsDefaultMark[] | null;
  children: DrawnChildren | null;
  comments: EverythingsComments | null;
  /** Only the name and emoji are known: no content or section was recorded, or it was pruned. */
  isNameOnly: boolean;
  /** Its page was recorded once and pruned to keep the cache in bounds. */
  isPruned: boolean;
};

/** The grid as the pane draws it. `isListed`: a full listing of the workspace was seen. */
export type DrawnGrid = {
  workspaces: EverythingsWorkspace[];
  landing: {
    workspaceId: string;
    things: EverythingsThingRef[];
    count: number;
    truncated: boolean;
    isListed: boolean;
  } | null;
};

/** A sub-thing as its row draws it: the ref, and its marks (null while unknown). */
export type DrawnChild = EverythingsThingRef & { marks: EverythingsRowMark[] | null };
export type DrawnChildren = { things: DrawnChild[]; count: number; truncated: boolean };

/** How many mark emojis a row shows before it says how many more there are. */
export const ROW_MARKS_SHOWN = 5;

/** The text a card or sub-thing row draws: the emoji (or NO_EMOJI), a separator, the name. */
function refCost(ref: EverythingsThingRef): number {
  return ref.name.length + (ref.emoji ?? NO_EMOJI).length + 1;
}

/** What a row's marks add to its label: up to ROW_MARKS_SHOWN emojis with spaces, "+n" and " | ". */
function rowMarksCost(marks: EverythingsRowMark[] | null): number {
  if (!marks || marks.length === 0) return 0;
  return marks.slice(0, ROW_MARKS_SHOWN).reduce((sum, mark) => sum + mark.emoji.length + 1, 0) + 8;
}

/** Keeps the refs that fit in `budget.left`, in order, and spends it. */
function fitRefs(refs: EverythingsThingRef[], budget: { left: number }): EverythingsThingRef[] {
  const kept: EverythingsThingRef[] = [];
  for (const ref of refs) {
    if (refCost(ref) > budget.left) break;
    budget.left -= refCost(ref);
    kept.push(ref);
  }
  return kept;
}

/** The text drawRequest in pane.tsx draws for a question. */
function requestCost(request: EverythingsRequest | null): number {
  if (!request) return 0;
  const options = request.options.reduce(
    (sum, option) => sum + option.label.length + (option.description?.length ?? 0) + 4,
    0,
  );
  const answer = request.answer;
  const answered = answer
    ? (answer.optionLabel?.length ?? 0) + (answer.comment?.length ?? 0) + (answer.userName?.length ?? 0) + 40
    : 40;
  return (request.createdBy?.length ?? 0) + 20 + request.question.length + options + answered;
}

/**
 * A cached thing as a page to draw. The page's text is spent in the order
 * the pane draws it, so what drops off first is the end of the page:
 * comments, then sub-things, then links that would have opened in the pane
 * (they open in the browser instead).
 */
export function fitPage(
  thing: EverythingsCachedThing,
  workspaceName: string | null,
  parent: EverythingsThingRef | null,
  defaultMarks: EverythingsDefaultMark[] | null,
  rowMarksOf: (thingId: string) => EverythingsRowMark[] | undefined = () => undefined,
): DrawnPage {
  const content = thing.content ?? null;
  const request = thing.request ?? null;
  const marks = thing.marks ?? null;
  const workspaceId = thing.workspaceId ?? null;
  const budget = { left: PAGE_TEXT_BUDGET - PAGE_CHROME };
  budget.left -= (workspaceName?.length ?? 0) + thing.name.length + (thing.emoji ?? NO_EMOJI).length + (thing.agent?.length ?? 0);
  // The header's Button back to the parent; its label never grows past the name it clips.
  budget.left -= parent ? refCost(parent) : 0;
  // A mark Button draws a state glyph, its emoji and its count; a default mark's draws the glyph and
  // the emoji. The line under the marks (a mark's name, at most 100, and a few words) is in PAGE_CHROME.
  budget.left -= (marks ?? []).reduce((sum, mark) => sum + mark.emoji.length + 10, 0);
  budget.left -= (defaultMarks ?? []).reduce((sum, mark) => sum + mark.emoji.length + 2, 0);
  budget.left -= (workspaceId ? thingUrl(workspaceId, thing.id).length : 0) + (content?.length ?? 0) + requestCost(request);

  const links: string[] = [];
  for (const href of content !== null ? thingLinks(content) : []) {
    if (href.length > budget.left) break;
    budget.left -= href.length;
    links.push(href);
  }

  let children: DrawnChildren | null = null;
  if (thing.children) {
    const kept: DrawnChild[] = [];
    for (const ref of thing.children.things) {
      const marks = rowMarksOf(ref.id) ?? null;
      const cost = refCost(ref) + rowMarksCost(marks);
      if (cost > budget.left) break;
      budget.left -= cost;
      kept.push({ ...ref, marks });
    }
    children = { things: kept, count: thing.children.count, truncated: thing.children.truncated || kept.length < thing.children.count };
  }

  let comments: EverythingsComments | null = null;
  if (thing.comments) {
    const kept: EverythingsComment[] = [];
    for (const comment of thing.comments.list) {
      // Drawn as the author, "via <agent>" and the text.
      const cost = comment.authorName.length + (comment.byAgent ? comment.byAgent.length + 4 : 0) + comment.text.length;
      if (cost > budget.left) break;
      budget.left -= cost;
      kept.push(comment);
    }
    comments = { list: kept, count: thing.comments.count, truncated: thing.comments.truncated || kept.length < thing.comments.count };
  }

  return {
    id: thing.id,
    name: thing.name,
    emoji: thing.emoji,
    workspaceId,
    workspaceName,
    parent,
    content,
    isContentCut: thing.isContentCut === true,
    links,
    agent: thing.agent ?? null,
    request,
    marks,
    defaultMarks,
    children,
    comments,
    isNameOnly: thing.pageSeen === 0,
    isPruned: thing.isPruned === true,
  };
}

/** A grid's workspaces and tiles, fitted to the text budget. */
export function fitGrid(
  workspaces: EverythingsWorkspace[],
  landing: { workspaceId: string; things: EverythingsThingRef[]; count: number; isListed: boolean } | null,
): DrawnGrid {
  const budget = { left: PAGE_TEXT_BUDGET - PAGE_CHROME };
  // A picker option draws its name, and its value may count as text too.
  const named = workspaces.filter(ws => {
    budget.left -= ws.name.length + ws.id.length;
    return budget.left > 0;
  });
  if (!landing) return { workspaces: named, landing: null };
  const things = fitRefs(landing.things, budget);
  return {
    workspaces: named,
    landing: {
      workspaceId: landing.workspaceId,
      things,
      count: Math.max(landing.count, landing.things.length),
      truncated: things.length < Math.max(landing.count, landing.things.length),
      isListed: landing.isListed,
    },
  };
}

files.hooks/follow.ts:
// Push follow: the pane shows what this session's agent writes, the moment
// the write resolves. register.tsx hands every finished Everythings call
// here from its `tool.call` hook, after `next(e)` resolved and before it
// returns the result untouched. An Everythings call is told by its tool name
// after the last `__`, whatever the server is called in this session.

import type { ToolCallResult } from 'claude-code';

import { recordCall } from './cache';
import {
  answerData,
  FOLLOWED_WRITES,
  GENERIC_TOOLS,
  READ_ONLY_TOOLS,
  isAnswered,
  splitToolName,
  UNIQUE_TOOLS,
  writeTarget,
} from './data';
import { agentCompletedView, followWrite, forgetFresh, refreshView } from './nav';
import type { Ports } from './ports';
import { isLearnedServer, learnServer } from './server';

/**
 * A call of a tool only Everythings has names its server, which the pane
 * learns. A call of a tool name other servers use too (`search`,
 * `add_comment`) counts only on the server already learned, so a Notion
 * search never repoints the pane.
 *
 * Every Everythings call the agent makes goes into the session cache, so
 * the pane can draw what it carried with no read of its own: a new thing
 * from create_thing's input and result, new content from update_thing's
 * result, a whole page from get_thing_view. Then a followed write points the
 * pane at what it touched, and one read of the pane's own tries to complete
 * the page, unless Claude Code refuses the pane's reads (blocked.ts). That
 * read is left running, so the agent's call never waits on it.
 */
export async function observeCall(
  p: Ports,
  tool: string,
  args: Record<string, unknown>,
  ran: ToolCallResult,
): Promise<void> {
  const parts = splitToolName(tool);
  if (!parts || !isAnswered(ran)) return;
  if (UNIQUE_TOOLS.has(parts.name)) await learnServer(p, parts.server);
  else if (!GENERIC_TOOLS.has(parts.name) || !(await isLearnedServer(p, parts.server))) return;

  const data = answerData(ran);
  const view = await p.view.read();
  const pinned = view.kind === 'thing' ? view.thingId : null;
  await p.cache.update(cache => recordCall(cache, parts.name, args, data, pinned));
  await agentCompletedView(p, parts.name, args, data);

  // Any write may have changed pages the cache cannot patch: none counts as fresh now.
  if (!READ_ONLY_TOOLS.has(parts.name)) await forgetFresh(p);
  if (!FOLLOWED_WRITES.has(parts.name)) return;
  const target = writeTarget(parts.name, args, data);
  if (!target) return;
  if (await followWrite(p, target)) void refreshView(p).catch(() => undefined);
}

