// The model-callable tool `mcp__everythings__show_thing`: when the person
// asks to see a thing or a workspace, the model calls it and the pane opens
// on it, drawn from what this session has seen and completed by one read of
// the pane's own (none while Claude Code refuses the pane's reads). It
// writes nothing. Its answer tells the model what the pane shows: when the
// pane could not read the thing and the session knows no more than its
// name, the model's own get_thing_view call fills the pane (the hook records
// its result). register.tsx lists the tool at session start and serves its
// calls.

import type { ToolSpec } from 'claude-code';

import { gridOf, pageOf } from './cache';
import { openGrid, openThing, readSnapshot } from './nav';
import { NOT_CONNECTED } from './pane';
import type { Ports } from './ports';

export const SHOW_THING: ToolSpec = {
  name: 'show_thing',
  description:
    'Shows an Everythings thing or workspace to the person in the Everythings pane beside this conversation. ' +
    'Call it when the person asks to see, show or open a thing ("show me my music thing") or a workspace: ' +
    "pass the thing's id as thingId, or a workspace's id as workspaceId. With neither, the pane opens on " +
    "the person's default workspace. Calling it only displays; it changes no data. Its answer says what the pane " +
    'shows; when it says the pane could not load the thing, call get_thing_view (or get_workspace_view) ' +
    'yourself and the pane shows its result. To read a thing for yourself, call get_thing instead.',
  inputSchema: {
    type: 'object',
    properties: {
      thingId: { type: 'string', description: 'The thing to show' },
      workspaceId: { type: 'string', description: 'The workspace to show when no thing is named' },
    },
    additionalProperties: false,
  },
};

function id(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

/** Said to the model while Claude Code refuses the pane's own reads. */
const BLOCKED = "Claude Code refuses the pane's own reads in this session.";

/** Opens the pane on what the call names; answers one line for the model. */
export async function showThing(p: Ports, args: Record<string, unknown>): Promise<string> {
  const thingId = id(args.thingId);
  const workspaceId = id(args.workspaceId);
  await p.openPane();
  if (thingId) await openThing(p, thingId);
  else await openGrid(p, workspaceId);

  const snap = await readSnapshot(p);
  const failure =
    snap.blocked !== null ? BLOCKED : (snap.load.error ?? (snap.load.isNotConnected ? NOT_CONNECTED : null));
  const why = snap.blocked !== null ? BLOCKED : `The pane's own read failed: ${failure}`;

  if (thingId) {
    const page = pageOf(snap.cache, thingId);
    // A page known only by name shows nothing the model could point the person to.
    const known = page !== null && !page.isNameOnly ? page : null;
    if (failure === null) return page ? `The Everythings pane shows "${page.name}".` : 'The Everythings pane is open.';
    if (known) {
      return `The Everythings pane shows "${known.name}" as this session's calls carried it; sections no call carried are missing. ${why}`;
    }
    return `The Everythings pane could not load it: ${failure} Call get_thing_view with thingId "${thingId}" yourself; the pane shows its result.`;
  }

  const grid = gridOf(snap.cache, snap.view.kind === 'grid' ? snap.view.workspaceId : workspaceId);
  const landing = grid.landing;
  const name = grid.workspaces.find(ws => ws.id === landing?.workspaceId)?.name ?? 'the';
  if (failure === null) return landing ? `The Everythings pane shows the "${name}" workspace.` : 'The Everythings pane is open.';
  if (landing && (landing.things.length > 0 || landing.isListed)) {
    return `The Everythings pane shows the things of the "${name}" workspace this session's calls carried. ${why}`;
  }
  const asked = workspaceId ? ` with workspaceId "${workspaceId}"` : '';
  return `The Everythings pane could not load it: ${failure} Call get_workspace_view${asked} yourself; the pane shows its result.`;
}

files.hooks/server.ts:
// Which MCP server the pane's reads go to.
//
// The same Everythings server runs under different names: a UUID for the
// claude.ai connector in the desktop app, `everythings` or
// `claude_ai_Everythings` in a terminal, `plugin_everythings_everythings`
// for this plugin's own .mcp.json entry. Reads try, in order: the name
// learned from an observed call (this session's, else the one kept in the
// store), then this plugin's own server through `$.mcp.connect`, then the
// claude.ai connector's display name. The first that answers is used for the
// rest of the session. Only a name learned from an observed call is kept in
// the store for later sessions.
//
// Claude Code may refuse the pane's own call: under auto permission mode it
// was seen refusing with "The server-side auto mode classifier gave no
// verdict ...". A refusal ends the read at once, with no other name tried
// and nothing retried; blocked.ts then stops the pane's reads until the
// person presses Refresh.

import type { McpToolResult } from 'claude-code';

import { oneLine } from './data';
import type { Ports } from './ports';

const STORE_KEY = 'server';
const OWN_SERVER = 'everythings';
const CLAUDE_AI_NAME = 'claude.ai Everythings';

/** No Everythings server answered. */
export class NotConnectedError extends Error {
  constructor() {
    super('The Everythings connector is not connected.');
    this.name = 'NotConnectedError';
  }
}

/** Claude Code refused the pane's call to `server`; the message is the engine's own words. */
export class RefusedError extends Error {
  constructor(
    readonly server: string,
    message: string,
  ) {
    super(message);
    this.name = 'RefusedError';
  }
}

/** The engine words a refusal `$.mcp.call(<server>, <tool>) refused: <reason>`. */
const REFUSED = /\brefused:/;

/** The server the session's reads go to, else the one kept from earlier sessions. */
export async function learnedServer(p: Ports): Promise<string | null> {
  const kept = await p.server.read();
  if (kept) return kept;
  const stored = await p.storeGet(STORE_KEY);
  return typeof stored === 'string' && stored ? stored : null;
}

/** True when `server` is the Everythings server already learned. */
export async function isLearnedServer(p: Ports, server: string): Promise<boolean> {
  return (await learnedServer(p)) === server;
}

/** An observed Everythings call named `server`: reads go there, now and in later sessions. */
export async function learnServer(p: Ports, server: string): Promise<void> {
  if ((await p.server.read()) !== server) await p.server.update(() => server);
  if ((await p.storeGet(STORE_KEY)) !== server) await p.storeSet(STORE_KEY, server);
}

/** What a rejected `$.mcp.call` says, without the engine's prefix. */
function reason(error: unknown): string {
  const text = error instanceof Error ? error.message : String(error);
  return oneLine(text.replace(/^[\s\S]*?\$\.mcp\.call:\s*/, '')) || 'The Everythings server did not answer.';
}

/**
 * One call of a write tool, on the learned server only: the one this
 * session's reads or calls reached, else the one kept in the store from an
 * earlier session's calls. No other name is tried and nothing is retried. A refusal throws RefusedError; no learned server throws
 * NotConnectedError; any other rejection throws its reason.
 */
export async function callLearnedServer(
  p: Ports,
  tool: string,
  args: Record<string, unknown>,
): Promise<McpToolResult> {
  const server = await learnedServer(p);
  if (!server) throw new NotConnectedError();
  try {
    return await p.mcpCall(server, tool, args);
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error);
    if (REFUSED.test(text)) throw new RefusedError(server, text);
    throw new Error(reason(error));
  }
}

/**
 * Calls a read tool on the first Everythings server that answers. A refusal
 * throws RefusedError at once. When no server answers, it throws
 * NotConnectedError, or the error of the server this session had been
 * reading from, which says more than "not connected" does.
 */
export async function callEverythings(
  p: Ports,
  tool: string,
  args: Record<string, unknown>,
): Promise<McpToolResult> {
  const tried = new Set<string>();
  const session = await p.server.read();
  let sessionError: string | null = null;

  const attempt = async (server: string | null): Promise<McpToolResult | null> => {
    if (!server || tried.has(server)) return null;
    tried.add(server);
    try {
      const result = await p.mcpCall(server, tool, args);
      if (server !== session) await p.server.update(() => server);
      return result;
    } catch (error) {
      const text = error instanceof Error ? error.message : String(error);
      if (REFUSED.test(text)) throw new RefusedError(server, text);
      if (server === session) sessionError = reason(error);
      return null;
    }
  };

  const first = await attempt(await learnedServer(p));
  if (first) return first;

  try {
    const own = await p.mcpConnect(OWN_SERVER);
    const answer = own.isConnected ? await attempt(own.server) : null;
    if (answer) return answer;
  } catch (error) {
    // A refusal ends the read; a connect that failed in any other way counts as no answer.
    if (error instanceof RefusedError) throw error;
  }

  const viaClaudeAi = await attempt(CLAUDE_AI_NAME);
  if (viaClaudeAi) return viaClaudeAi;

  if (sessionError !== null) throw new Error(sessionError);
  throw new NotConnectedError();
}

files.hooks/blocked.ts:
// When Claude Code refuses the pane's own reads.
//
// Under auto permission mode Claude Code was seen (2026-10-03, desktop Code
// tab) refusing every `$.mcp.call` the pane made, and repeating the call
// never helped. So the first refusal puts the pane in blocked mode for the
// session: navigation draws from the session cache at once and makes no read
// attempt, and no error line or Retry button shows. Refresh is the one way
// to try again: a read that succeeds ends blocked mode, another refusal
// keeps it quietly.
//
// While blocked, the pane shows one note: why it draws only what Claude has
// read, and the permission rules for its four read tools, with a Button that
// copies them. An allow rule for the two page reads was seen to lift the
// refusal. The search's rule is there too though a refused search blocks
// nothing (nav.ts): one copy then lets `/findthing` run as well. A refusal
// of a write (writes.ts) shows the same kind of note with that write's
// rules, beside the reads' note. The reads' note's Dismiss holds for the
// session (`$.state`) and for later sessions (`$.store`), until a Refresh
// the person presses is refused: that shows the note again, since it says
// why nothing changed, and clears the stored dismissal.

import type { RenderSurface } from 'claude-code';

import { READ_TOOLS, WRITE_TOOLS } from './data';
import type { Ports } from './ports';
import type { RefusedError } from './server';

const NOTE_DISMISSED = 'readsNoteDismissed';

const PANE_TOOLS = [...Object.values(READ_TOOLS), ...Object.values(WRITE_TOOLS)]
  .sort((a, b) => b.length - a.length)
  .join('|');
/** A tool name the engine's refusal named, which gives the server as permission rules spell it. */
const NAMED_TOOL = new RegExp(`\\bmcp__([A-Za-z0-9_-]+?)__(?:${PANE_TOOLS})\\b`);

/** The read tools the note asks to allow: every read the pane makes, so one copy covers the whole pane. */
export const READ_RULE_TOOLS: readonly string[] = [READ_TOOLS.thing, READ_TOOLS.grid, READ_TOOLS.defaults, READ_TOOLS.search];

/**
 * The allow rules for `tools` on the server that refused. The server part
 * is the one the refusal named, else the server's name with every character
 * a tool name cannot hold made `_`, as Claude Code does (`claude.ai
 * Everythings` is `claude_ai_Everythings`).
 */
export function rulesFor(refused: RefusedError, tools: readonly string[]): string[] {
  const spelled = NAMED_TOOL.exec(refused.message)?.[1] ?? refused.server.replace(/[^A-Za-z0-9_-]/g, '_');
  return tools.map(tool => `mcp__${spelled}__${tool}`);
}

export async function isBlocked(p: Ports): Promise<boolean> {
  return (await p.blocked.read()) !== null;
}

/** A refused read: the pane stops reading until Refresh. A note dismissed in an earlier session stays dismissed. */
export async function block(p: Ports, refused: RefusedError): Promise<void> {
  if (!(await p.noteDismissed.read())) {
    let isDismissed = false;
    try {
      isDismissed = (await p.storeGet(NOTE_DISMISSED)) === true;
    } catch {
      // An unreadable store shows the note; dismissing it writes the store again.
    }
    if (isDismissed) await p.noteDismissed.update(() => true);
  }
  const rules = rulesFor(refused, READ_RULE_TOOLS);
  await p.blocked.update(last =>
    last !== null && last.rules.join('\n') === rules.join('\n') ? last : { rules, copy: null },
  );
}

/** A read that succeeded: the pane reads again, and the note goes. */
export async function unblock(p: Ports): Promise<void> {
  if (await isBlocked(p)) await p.blocked.update(() => null);
}

export async function dismissNote(p: Ports): Promise<void> {
  await p.noteDismissed.update(() => true);
  await p.storeSet(NOTE_DISMISSED, true);
}

/**
 * A Refresh the person pressed was refused: the note shows again, and the
 * stored dismissal goes, so later sessions show it too until Dismiss.
 */
export async function showNote(p: Ports): Promise<void> {
  await p.noteDismissed.update(() => false);
  if ((await p.storeGet(NOTE_DISMISSED)) === true) await p.storeSet(NOTE_DISMISSED, false);
}

/** Puts a note's rules on the clipboard of the surface the press came from, one per line. */
async function copied(p: Ports, rules: string[], surface: RenderSurface): Promise<'copied' | 'failed'> {
  try {
    return (await p.copy(rules.join('\n'), surface)) ? 'copied' : 'failed';
  } catch {
    return 'failed';
  }
}

/** Copies the read rules, or with `on: 'writes'` a refused write's, and says how it went. */
export async function copyRules(p: Ports, on: 'reads' | 'writes', surface: RenderSurface): Promise<void> {
  if (on === 'reads') {
    const blocked = await p.blocked.read();
    if (blocked === null) return;
    const copy = await copied(p, blocked.rules, surface);
    await p.blocked.update(last => (last === null ? last : { ...last, copy }));
  } else {
    const blocked = (await p.writes.read()).blocked;
    if (blocked === null) return;
    const copy = await copied(p, blocked.rules, surface);
    await p.writes.update(last => (last.blocked === null ? last : { ...last, blocked: { ...last.blocked, copy } }));
  }
}

files.hooks/writes.ts:
// The person's own writes from the pane: their mark on a press, their
// comment on a submit. The pane writes nothing else: no answer to an
// agent's question (it would ride the agent's token and read as the agent
// answering itself), no content, no reply.
//
// Each write is one `$.mcp.call` on the learned server (server.ts), never
// retried. While it is in flight its Button or field cannot send again; the
// marker is cleared however the call ends, and one older than 30 seconds
// (left by an earlier load) blocks nothing. A plugin's `$.mcp.call` raises
// the `mcp.call` event, which follow does not hook, so nothing follows these
// calls. On success the answer goes through recordCall, the same code that
// records the agent's own add_mark, remove_mark and add_comment, so the
// count, `mine` and the comment list stay true with no read. An `isError`
// answer or a rejection changes nothing and leaves one line with the
// server's text. A refusal by Claude Code leaves a line where the person
// pressed and a note with the rules that let that write through.

import type { EverythingsWrites } from '../types';
import { rulesFor } from './blocked';
import { PERSON_AUTHOR, recordCall } from './cache';
import { COMMENT_LIMIT, readResult, WRITE_STALE_MS, WRITE_TOOLS } from './data';
import type { Ports } from './ports';
import { callLearnedServer, NotConnectedError, RefusedError } from './server';

export const NOT_REACHED = 'The pane has not reached Everythings yet in this session. Press Refresh first.';
export const TOO_LONG = `A comment holds at most ${COMMENT_LIMIT.toLocaleString('en-US')} characters.`;
/** Said where the person pressed when Claude Code refused the write. */
export const WRITE_REFUSED: Record<'mark' | 'comment', string> = {
  mark: "Claude Code's permission mode blocked the mark.",
  comment: "Claude Code's permission mode blocked the comment.",
};
/** At most this many things keep a count of comments posted from the pane. */
const POSTED_KEPT = 300;

/** A mark Button: a mark the thing carries, or a default mark it does not. */
export type MarkPress = { name: string; emoji: string };

type Written =
  | { ok: true; data: Record<string, unknown> | null }
  | { ok: false; text: string | null; refused: RefusedError | null };

async function write(p: Ports, tool: string, args: Record<string, unknown>): Promise<Written> {
  try {
    const answer = readResult(await callLearnedServer(p, tool, args));
    return 'error' in answer ? { ok: false, text: answer.error, refused: null } : { ok: true, data: answer.data };
  } catch (error) {
    if (error instanceof RefusedError) return { ok: false, text: null, refused: error };
    if (error instanceof NotConnectedError) return { ok: false, text: NOT_REACHED, refused: null };
    return { ok: false, text: error instanceof Error ? error.message : String(error), refused: null };
  }
}

/** Records a write that went through, as recordCall records the agent's. */
async function recordWrite(
  p: Ports,
  tool: string,
  args: Record<string, unknown>,
  data: Record<string, unknown> | null,
  author?: string,
): Promise<void> {
  const view = await p.view.read();
  const pinned = view.kind === 'thing' ? view.thingId : null;
  await p.cache.update(cache => recordCall(cache, tool, args, data ?? { action: 'unchanged' }, pinned, author));
}

/** True while a marker stamped `at` still counts at `now`. */
export function isLive(at: number | undefined, now: number): boolean {
  return at !== undefined && now - at < WRITE_STALE_MS;
}

/** The markers that still count. */
function live(markers: Record<string, number>, now: number): Record<string, number> {
  return Object.fromEntries(Object.entries(markers).filter(([, at]) => isLive(at, now)));
}

function without(markers: Record<string, number>, key: string): Record<string, number> {
  const { [key]: _gone, ...rest } = markers;
  return rest;
}

/** How a write ended, written back: an error or refusal line, the note, or a note cleared by a write that went through. */
function settled(
  writes: EverythingsWrites,
  thingId: string,
  on: 'mark' | 'comment',
  written: Written | null,
): Pick<EverythingsWrites, 'error' | 'blocked'> {
  if (written === null) return { error: writes.error, blocked: writes.blocked };
  if (written.ok) return { error: writes.error, blocked: writes.blocked?.on === on ? null : writes.blocked };
  if (written.refused !== null) {
    const tools = on === 'mark' ? [WRITE_TOOLS.addMark, WRITE_TOOLS.removeMark] : [WRITE_TOOLS.comment];
    return {
      error: { thingId, on, text: WRITE_REFUSED[on] },
      blocked: { on, rules: rulesFor(written.refused, tools), copy: null },
    };
  }
  return { error: written.text !== null ? { thingId, on, text: written.text } : writes.error, blocked: writes.blocked };
}

function markKey(thingId: string, name: string): string {
  return `${thingId} ${name}`;
}

/** What the line under the marks says once a mark call went through. */
function markDone(tool: string, data: Record<string, unknown> | null): NonNullable<EverythingsWrites['last']>['did'] {
  const action = data?.action;
  if (tool === WRITE_TOOLS.addMark) return action === 'created' ? 'added' : 'already-on';
  return action === 'deleted' ? 'removed' : 'already-off';
}

/**
 * A press on a mark: the person's mark comes off when the cache says it is
 * theirs as the press runs, else goes on.
 */
export async function pressMark(p: Ports, thingId: string, mark: MarkPress): Promise<void> {
  const key = markKey(thingId, mark.name);
  const cached = (await p.cache.read()).things[thingId]?.marks?.find(one => one.name === mark.name);
  const isTheirs = cached?.mine === true;
  const now = await p.now();
  let isMine = false;
  await p.writes.update(writes => {
    const pending = live(writes.pending, now);
    isMine = pending[key] === undefined;
    if (!isMine) return writes;
    const error = writes.error?.thingId === thingId && writes.error.on === 'mark' ? null : writes.error;
    const did = isTheirs ? 'removing' : 'adding';
    return {
      ...writes,
      pending: { ...pending, [key]: now },
      error,
      last: { thingId, name: mark.name, emoji: mark.emoji, did, at: now },
    };
  });
  if (!isMine) return;

  const tool = isTheirs ? WRITE_TOOLS.removeMark : WRITE_TOOLS.addMark;
  const args = isTheirs ? { thingId, name: mark.name } : { thingId, emoji: mark.emoji, name: mark.name };
  let written: Written | null = null;
  try {
    written = await write(p, tool, args);
    if (written.ok) await recordWrite(p, tool, args, written.data);
  } finally {
    const outcome = written;
    await p.writes.update(writes => {
      const isLatest = writes.last?.thingId === thingId && writes.last.name === mark.name && writes.last.at === now;
      const last =
        !isLatest || writes.last === null
          ? writes.last
          : outcome?.ok === true
            ? { ...writes.last, did: markDone(tool, outcome.data) }
            : null;
      return { ...writes, pending: without(writes.pending, key), ...settled(writes, thingId, 'mark', outcome), last };
    });
  }
}

/**
 * A submitted comment, top level, sent as typed. Blank text sends nothing;
 * text past the server's limit sends nothing and says so. On success that
 * thing's field is drawn afresh (`posted`), empty; on a failure it stays as
 * typed. A comment in flight on one thing holds back only that thing's field.
 */
export async function submitComment(p: Ports, thingId: string, text: string): Promise<void> {
  if (!text.trim()) return;
  if (text.length > COMMENT_LIMIT) {
    await p.writes.update(writes => ({ ...writes, error: { thingId, on: 'comment', text: TOO_LONG } }));
    return;
  }
  const now = await p.now();
  let isMine = false;
  await p.writes.update(writes => {
    const commenting = live(writes.commenting, now);
    isMine = commenting[thingId] === undefined;
    if (!isMine) return writes;
    const error = writes.error?.thingId === thingId && writes.error.on === 'comment' ? null : writes.error;
    return { ...writes, commenting: { ...commenting, [thingId]: now }, error };
  });
  if (!isMine) return;

  const args = { thingId, content: text };
  let written: Written | null = null;
  try {
    written = await write(p, WRITE_TOOLS.comment, args);
    if (written.ok) await recordWrite(p, WRITE_TOOLS.comment, args, written.data, PERSON_AUTHOR);
  } finally {
    const outcome = written;
    await p.writes.update(writes => {
      let posted = writes.posted;
      if (outcome?.ok === true) {
        const { [thingId]: count = 0, ...others } = writes.posted;
        // The latest posts last, so the oldest go first past the bound.
        posted = Object.fromEntries([...Object.entries(others).slice(-(POSTED_KEPT - 1)), [thingId, count + 1]]);
      }
      return { ...writes, commenting: without(writes.commenting, thingId), posted, ...settled(writes, thingId, 'comment', outcome) };
    });
  }
}

export async function dismissWriteNote(p: Ports): Promise<void> {
  await p.writes.update(writes => (writes.blocked === null ? writes : { ...writes, blocked: null }));
}

/** The screen changed: a failure line and a mark's line left on the last page go. */
export async function leaveWrites(p: Ports): Promise<void> {
  await p.writes.update(writes =>
    writes.error === null && writes.last === null ? writes : { ...writes, error: null, last: null },
  );
}

